import { computed,onMounted,ref } from 'vue'; import { useRouter } from 'vue-router'; import { ArrowRight,Calendar,Document } from '@element-plus/icons-vue'; import { ACADEMIC_CONFERENCE_COUNT } from '@/config/knowledgeStats'; import { fetchCategories,fetchPaperVenues } from '@/services/api'; import { fetchRetrievalHealth } from '@/services/retrieval'; import type { Category } from '@/types/conference'; import type { PaperVenue } from '@/types/paper'
const router=useRouter(),venues=ref<PaperVenue[]>([]),categories=ref<Category[]>([]),retrievalPaperCount=ref<number|null>(null),loading=ref(true); const topVenues=computed(()=>[...venues.value].sort((a,b)=>b.count-a.count).slice(0,5)); const yearRange=computed(()=>venues.value.length?`${Math.min(...venues.value.map(v=>v.minYear))}—${Math.max(...venues.value.map(v=>v.maxYear))}`:'—'); const compact=(n:number)=>n>=10000?`${(n/10000).toFixed(1)}万`:n.toLocaleString('zh-CN'); const openVenue=(venue:string)=>router.push({name:'conference-detail',params:{venue}})
